int osal_valloc_msg_wait(unsigned dst,void **out,unsigned n,unsigned wait){int saved=*__errno_location();init();if(!alloc_next)return -1021;unsigned op=0;int slot=-1;U sequence=0,tid=0,caller=(U)__builtin_return_address(0),frame=(U)__builtin_frame_address(0);struct lp_di di={0};if(enabled()&&((dst==0x8280074dU&&n==12)||(dst==0x8280084dU&&n==36)||(dst==0x8280084eU&&n==8))&&dladdr((void *)caller,&di)&&di.base&&di.file&&(!strcmp(di.file,"libObj.so")||!strcmp(di.file,"/usr/lib/libObj.so")))op=lp_role(dst,n,caller-(U)di.base);if(op){tid=syscall(178);enter();if(!owner)owner=syscall(172);sequence=++ledger.allocations;for(unsigned i=0;i<8;i++)if(!active[i].sequence){slot=i;break;}if(slot>=0){active[slot].sequence=sequence;active[slot].tid=tid;active[slot].caller=caller;active[slot].frame=frame;active[slot].since=now_ns();active[slot].destination=dst;active[slot].bytes=n;active[slot].wait=wait;}leave();dprintf(2,"FX3_OSD_LIFE_ALLOC_BEGIN sequence=%lu tid=%lu destination=%#x bytes=%u wait=%u op=%x native_caller=%#lx original_follows=1\n",sequence,tid,dst,n,wait,op,caller-(U)di.base);}*__errno_location()=saved;int rc=alloc_next(dst,out,n,wait);int after=*__errno_location();if(op){U pointer=out?(U)*out:0;enter();if(slot>=0)memset(active+slot,0,sizeof active[slot]);int record=lp_return(&ledger,pointer,dst,n,op,rc);U live=ledger.live,reuse=ledger.reuses;leave();dprintf(2,"FX3_OSD_LIFE_ALLOC_RETURN sequence=%lu tid=%lu destination=%#x bytes=%u pointer=%#lx result=%d errno=%d record=%d tracked_live=%lu native_reuses_without_user_free=%lu\n",sequence,tid,dst,n,pointer,rc,after,record,live,reuse);}*__errno_location()=after;return rc;}
